import React, { useState } from 'react';
import MenuIcon from '@mui/icons-material/Menu';
import SearchIcon from '@mui/icons-material/Search';
import { styled, alpha, createTheme, ThemeProvider } from '@mui/material/styles';
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Toolbar from '@mui/material/Toolbar';
import InputBase from '@mui/material/InputBase';
import { Button, Stack } from '@mui/material';
import useMediaQuery from '@mui/material/useMediaQuery';
import logo from './assets/techcareer-logo.svg';
import { Link } from 'react-router-dom';

const theme = createTheme({
  typography: {
    fontFamily: 'Roboto, sans-serif', // Roboto'yu öncelikli yapıyoruz
    fontSize: 14, // Font boyutu 14px
  },
});

const Search = styled('div')(({ theme }) => ({
  position: 'relative',
  borderRadius: theme.shape.borderRadius,
  backgroundColor: 'white',
  border: '1px solid #ccc',
  '&:hover': {
    backgroundColor: alpha(theme.palette.common.black, 0.06),
  },
  width: '300px',
  marginLeft: theme.spacing(2),
  [theme.breakpoints.down('md')]: {
    display: 'none',
  },
}));

const SearchIconWrapper = styled('div')(({ theme }) => ({
  padding: theme.spacing(0, 2),
  height: '100%',
  position: 'absolute',
  pointerEvents: 'none',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  color: 'black', // Arama ikonu rengi siyah yapıldı
}));

const StyledInputBase = styled(InputBase)(({ theme }) => ({
  color: 'black',
  '& .MuiInputBase-input': {
    padding: theme.spacing(1, 1, 1, 0),
    paddingLeft: `calc(1em + ${theme.spacing(4)})`,
    width: '250px',
    transition: theme.transitions.create('width'),
    color: 'black',
    '&::placeholder': {
      color: 'rgba(0, 0, 0, 0.6)',
      opacity: 1,
    },
  },
}));

export default function PrimarySearchAppBar() {
  const [anchorEl, setAnchorEl] = useState(null);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const isMobile = useMediaQuery('(max-width:1100px)');

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleSearchToggle = () => {
    setIsSearchOpen((prev) => !prev);
  };

  return (
    <ThemeProvider theme={theme}>
      <Box sx={{ flexGrow: 1 }}>
        <AppBar
          position="static"
          sx={{
            backgroundColor: 'white',
            boxShadow: '0px 2px 4px rgba(0, 0, 0, 0.1)', // Navbar altına shadow eklendi
          }}
        >
          <Toolbar
            sx={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              paddingX: { xs: 1, sm: 3 },
            }}
          >
            {/* Logo */}
            <Box
              sx={{
                display: 'flex',
                justifyContent: 'center',
                flexGrow: 1,
              }}
            >
              <Link to="/" style={{ display: 'flex', justifyContent: 'center' }}>
                <img
                  src={logo}
                  alt="logo"
                  style={{
                    width: 'auto',
                    height: '25px',
                    maxWidth: '200px',
                  }}
                />
              </Link>
            </Box>

            {/* Desktop Search */}
            {!isMobile && (
              <Box
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                <Search>
                  <SearchIconWrapper>
                    <SearchIcon />
                  </SearchIconWrapper>
                  <StyledInputBase
                    placeholder="Etkinlik, İş ilanı, Blog ara"
                    inputProps={{ 'aria-label': 'search' }}
                  />
                </Search>

                {/* Desktop Buttons */}
                <Stack direction="row" spacing={2} sx={{ marginLeft: 3 }}>
                  <Button variant="text" sx={{ color: 'black', whiteSpace: 'nowrap' }}>
                    Etkinlikler
                  </Button>
                  <Button variant="text" sx={{ color: 'black', whiteSpace: 'nowrap' }}>
                    İş ilanları
                  </Button>
                  <Button variant="text" sx={{ color: 'black', whiteSpace: 'nowrap' }}>
                    Eğitimler
                  </Button>
                  <Button variant="text" sx={{ color: 'black', whiteSpace: 'nowrap' }}>
                    Komünite
                  </Button>
                  <Button variant="text" sx={{ color: 'black', whiteSpace: 'nowrap' }}>
                    Şirketler
                  </Button>
                </Stack>
              </Box>
            )}

            {/* Giriş/Üye Ol Button */}
            <Button
              variant="contained"
              sx={{
                backgroundColor: '#1eb96b',
                color: 'white',
                whiteSpace: 'nowrap',
                '&:hover': { backgroundColor: '#1aa65f' },
              }}
            >
              Giriş/Üye Ol
            </Button>
          </Toolbar>
        </AppBar>
      </Box>
    </ThemeProvider>
  );
}
